        &*tables
    };

    let mut sample_difference_abs = sample_difference;
    if sample_difference_abs < 0 {
        sample_difference_abs = -sample_difference_abs;
    }
    const CLIP23: int32_t = ((1 as c_int as int32_t) << 23) - 1;
    if sample_difference_abs > CLIP23 {
        sample_difference_abs = CLIP23;
    }

    let intervals_base = tables_ref.quantize_intervals;
    let mut quantized_sample = aptx_bin_search(
        sample_difference_abs >> 4,
        quantization_factor,
        intervals_base,
        tables_ref.tables_size,
    );

    let mut d = rshift32_clip24(
        (dither as int64_t * dither as int64_t >> 32) as int32_t,
        7 as c_uint,
    ) - ((1 as c_int as int32_t) << 23);

    let qdf = unsafe { // SAFETY: quantized_sample is produced by aptx_bin_search for these tables and is used as an in-bounds index exactly as in the original code.
        *tables_ref.quantize_dither_factors.offset(quantized_sample as isize)
