    d = rshift64(d as int64_t * qdf as int64_t, 23 as c_uint) as int32_t;

    let intervals = unsafe { // SAFETY: quantized_sample is the same index used by the original code to offset into quantize_intervals.
        intervals_base.offset(quantized_sample as isize)
    };
    let i0 = unsafe { // SAFETY: original code reads intervals[0] and intervals[1]; same preconditions apply here.
        *intervals
    };
    let i1 = unsafe { // SAFETY: original code reads intervals[0] and intervals[1]; same preconditions apply here.
