    let interval = (i1 - i0) * sign;

    let dithered_sample = rshift64_clip24(
        dither as int64_t * interval as int64_t
            + ((clip_intp2(mean + d, 23 as c_uint) as int64_t) << 32),
        32 as c_uint,
    );

    let error = ((sample_difference_abs as int64_t) << 20)
        - dithered_sample as int64_t * quantization_factor as int64_t;

    let mut err32 = rshift64(error, 23 as c_uint) as int32_t;
